var i=103;var n=[{id:`cooking-103-01`,theoryId:103,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What mainly does blanching do before freezing many vegetables?`,ua:`Для чого переважно бланшують багато овочів перед заморожуванням?`},explanation:{en:`Blanching limits enzyme-driven quality changes during frozen storage.`,ua:`Бланшування обмежує ферментативні зміни якості під час замороженого зберігання.`},options:[{id:`a`,text:{en:`Slows quality loss by inactivating enzymes`,ua:`Сповільнює втрату якості, інактивуючи ферменти`}},{id:`b`,text:{en:`Makes food sterile forever`,ua:`Назавжди робить продукт стерильним`}},{id:`c`,text:{en:`Removes every vitamin`,ua:`Видаляє всі вітаміни`}}],answer:{optionIds:[`a`]}},{id:`cooking-103-02`,theoryId:103,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Frozen vegetables can sometimes be as nutritious as fresh vegetables, depending on handling and storage.`,ua:`Заморожені овочі іноді можуть бути не менш поживними за свіжі залежно від обробки та зберігання.`},explanation:{en:`Nutrient retention depends on time, processing and storage, not only fresh versus frozen labels.`,ua:`Збереження нутрієнтів залежить від часу, обробки та зберігання, а не тільки від позначки «свіжі» чи «заморожені».`},answer:{value:!0}},{id:`cooking-103-03`,theoryId:103,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match produce format to a practical consideration.`,ua:`Поєднайте форму продукту з практичною особливістю.`},explanation:{en:`All formats can be useful with appropriate inspection and storage.`,ua:`Усі форми можуть бути доречними за правильного огляду та зберігання.`},leftItems:[{id:`l1`,text:{en:`Fresh produce`,ua:`Свіжі продукти`}},{id:`l2`,text:{en:`Frozen vegetables`,ua:`Заморожені овочі`}},{id:`l3`,text:{en:`Canned vegetables`,ua:`Консервовані овочі`}}],rightItems:[{id:`r3`,text:{en:`Check packaging integrity and added salt`,ua:`Перевірити цілісність тари та додану сіль`}},{id:`r2`,text:{en:`Manage freezer storage and thawing instructions`,ua:`Дотримуватися правил морозильного зберігання та розморожування`}},{id:`r1`,text:{en:`Inspect freshness and wash when appropriate`,ua:`Перевірити стан і за потреби помити`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-103-04`,theoryId:103,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You need spinach for soup outside its season. What is a practical option?`,ua:`Вам потрібен шпинат для супу не в сезон. Що доцільно обрати?`},explanation:{en:`Frozen produce is a reliable ingredient when stored and used correctly.`,ua:`Заморожені овочі — надійний інгредієнт за належного зберігання та використання.`},options:[{id:`a`,text:{en:`Properly stored frozen spinach`,ua:`Правильно збережений заморожений шпинат`}},{id:`b`,text:{en:`Spinach with obvious mold`,ua:`Шпинат із видимою пліснявою`}},{id:`c`,text:{en:`Leaves left warm for days`,ua:`Листя, яке кілька днів лежало в теплі`}}],answer:{optionIds:[`a`]}},{id:`cooking-103-05`,theoryId:103,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which comparison is inaccurate?`,ua:`Яке порівняння неправильне?`},explanation:{en:`Freezing does not eliminate all nutrients.`,ua:`Заморожування не знищує всі поживні речовини.`},options:[{id:`a`,text:{en:`Some canned products contain added sodium`,ua:`Деякі консерви містять доданий натрій`}},{id:`b`,text:{en:`Blanching can protect frozen vegetable quality`,ua:`Бланшування може захищати якість заморожених овочів`}},{id:`c`,text:{en:`Every frozen vegetable has zero nutrients`,ua:`Усі заморожені овочі не містять поживних речовин`}}],answer:{optionIds:[`c`]}},{id:`cooking-103-06`,theoryId:103,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`What are reasonable actions when using frozen vegetables?`,ua:`Які дії доречні для заморожених овочів?`},explanation:{en:`Freezing preserves quality but does not reliably sterilize food.`,ua:`Заморожування зберігає якість, але не гарантує стерильності.`},options:[{id:`a`,text:{en:`Check package and storage condition`,ua:`Перевірити пакування та умови зберігання`}},{id:`b`,text:{en:`Follow cooking instructions`,ua:`Дотримуватися інструкцій приготування`}},{id:`c`,text:{en:`Assume freezing sterilizes all food`,ua:`Вважати, що заморожування стерилізує всю їжу`}},{id:`d`,text:{en:`Control time after thawing`,ua:`Контролювати час після розморожування`}}],answer:{optionIds:[`a`,`b`,`d`]}}];var a={theoryId:103,exercises:n};export{a as default,n as exercises,i as theoryId};